// elunic: on room entry, put players who own a desk (personal area) onto its chair.
// Generated by build.py; SPAWNS maps desk area id -> [x, y, facing] of its chair (centre in pixels), CHAIRS lists
// every seat on the map as [x, y, facing]. facing ("up" | "down" | "left" | "right") points towards the table.
// Test map: no calendar pings (wa-calendar still assigns seats of the live map).
const CALENDAR = false;
const SPAWNS = {"cfce74cb-2d01-5f26-b56a-aa89ad4c3852": [212, 526, "right"], "98b2ba06-bad4-5da9-b3dc-62f14689c0f4": [212, 610, "right"], "bc909578-d7ec-5fbe-b1df-9e657830a71e": [212, 697, "right"], "3f0001ce-8cc9-55dd-935b-f52baf13a566": [298, 526, "left"], "0a395e3c-722f-5821-bec1-7151e2fca26a": [298, 610, "left"], "7164bfb0-de9c-5f92-bc67-22e101863b3f": [298, 697, "left"], "347cde93-9505-5d5b-9907-ba2a0d06fccc": [372, 526, "right"], "8305f062-c540-5c69-8846-5bcf77920a8a": [372, 610, "right"], "7d2c0095-a765-5db1-aefd-186e3eb0283f": [372, 697, "right"], "f34d70ff-1a1d-5e59-b12b-de9d69f1cda0": [458, 526, "left"], "c2f07d89-0c35-5bdd-9bcd-9c187e044cf8": [458, 610, "left"], "b2e5a0f7-4524-50b0-a0ce-f67f400ecfdd": [458, 697, "left"], "ee1e9c39-3276-5598-ad18-441986fdf1f3": [533, 526, "right"], "f259fb2c-d2cb-5934-bd1c-6b9c96013a44": [533, 610, "right"], "5e38c196-60d0-58b5-9541-0edbdc0d58f3": [533, 697, "right"], "51fc2044-7a84-5b20-9983-8f3f6627655f": [618, 526, "left"], "db58b61f-bcdd-52d7-9fe5-a1652bb6b8d5": [618, 610, "left"], "42e49b50-efa6-50de-a0a9-fdc436a24f66": [618, 697, "left"], "589ccf5d-10e0-5a49-89b9-dc2229e3fdc2": [693, 526, "right"], "eaa38885-4af3-5375-b7e7-0145188dbf0d": [693, 610, "right"], "60c3f0c7-0c9b-512b-a1ab-57633258cb6c": [693, 697, "right"], "b8a2b219-7cd9-5570-b69a-3e877f9c3b9a": [780, 526, "left"], "e24e8c86-9faf-5c7a-bd34-29317550506a": [780, 610, "left"], "b80a53df-3b94-5976-882e-5952ea9f97fc": [780, 697, "left"], "99fdc83e-1c4a-53da-bbe2-5bb2f266de5c": [94, 386, "left"], "bfc0b842-bb90-52af-92b0-34a17edef0d5": [95, 501, "left"], "03234837-f42a-5b4e-b23b-915081510735": [95, 619, "left"], "66becdd8-149c-5f7d-9da8-4e49bac1357b": [94, 730, "left"], "4272d5a3-adb0-54a9-a018-776bcfc66c44": [918, 684, "left"], "cbe9006e-af50-5b36-861e-f12ffc6e8789": [1036, 683, "right"], "5175b004-7e2d-58fd-b7a9-70d5777c4fe5": [939, 476, "up"], "d34b43a5-30ee-548c-9df9-70444c0ca89b": [1013, 474, "up"]};
const CHAIRS = [[212, 526, "right"], [212, 610, "right"], [212, 697, "right"], [298, 526, "left"], [298, 610, "left"], [298, 697, "left"], [372, 526, "right"], [372, 610, "right"], [372, 697, "right"], [458, 526, "left"], [458, 610, "left"], [458, 697, "left"], [533, 526, "right"], [533, 610, "right"], [533, 697, "right"], [618, 526, "left"], [618, 610, "left"], [618, 697, "left"], [693, 526, "right"], [693, 610, "right"], [693, 697, "right"], [780, 526, "left"], [780, 610, "left"], [780, 697, "left"], [94, 386, "left"], [95, 501, "left"], [95, 619, "left"], [94, 730, "left"], [918, 684, "left"], [1036, 683, "right"], [939, 476, "up"], [1013, 474, "up"], [113, 80, "down"], [173, 80, "down"], [113, 275, "up"], [173, 275, "up"], [392, 163, "down"], [440, 106, "down"], [472, 106, "down"], [514, 110, "down"], [514, 145, "left"], [514, 180, "left"], [1163, 555, "right"], [1163, 595, "right"], [1163, 633, "right"], [1163, 673, "right"], [1220, 555, "left"], [1220, 595, "left"], [1220, 633, "left"], [1220, 673, "left"], [1307, 568, "right"], [1307, 620, "right"], [1384, 568, "left"], [1384, 620, "left"], [1599, 123, "left"], [1599, 165, "left"], [1599, 205, "left"], [1712, 134, "down"], [1749, 134, "down"], [1787, 134, "down"], [1712, 212, "up"], [1749, 212, "up"], [1787, 212, "up"], [1792, 88, "up"], [1832, 88, "up"], [1572, 547, "down"], [1621, 547, "down"], [1669, 547, "down"], [1716, 547, "down"], [1762, 547, "down"], [1810, 547, "down"], [1858, 547, "down"], [1572, 650, "up"], [1621, 650, "up"], [1669, 650, "up"], [1716, 650, "up"], [1762, 650, "up"], [1810, 650, "up"], [1858, 650, "up"], [1815, 373, "down"], [1880, 440, "left"]];
// Conference rooms of the calendar service (same ids as elunic-rooms.json): interior [x, y, width, height] in pixels.
const ROOM_RECTS = {"conference-big": [1472, 448, 448, 320], "conference-small": [1152, 448, 96, 320], "meeting-four": [1280, 448, 160, 320], "lounge": [32, 32, 544, 256]};

// The play frontend (elunic seat bridge) walks the player straight onto a chair and turns it; the scripting API can
// neither walk inside a tile nor set the facing direction. Only this script's iframe is trusted by the bridge.
const face = (direction) => window.parent.postMessage({ type: "elunic-face", direction }, "*");
const sit = (c) => window.parent.postMessage({ type: "elunic-sit", x: c[0], y: c[1], direction: c[2] }, "*");
// Images without the seat bridge do not answer the hello: the chair snap then keeps teleporting.
let seatBridge = false;
window.addEventListener("message", (e) => { if (e.data && e.data.type === "elunic-seat-bridge") seatBridge = true; });
window.parent.postMessage({ type: "elunic-seat-hello" }, "*");
// facing of the chair at (x, y), if there is one (calendar seats are tile centres, wide chairs are centred on two tiles)
// True while the calendar moves the player: the chair snap stays out of the way (its walk would reset the status).
let scriptedMove = false;
const nearestChair = (x, y, maxPx) => {
    let best = null, bestDist = Infinity;
    for (const c of CHAIRS) {
        const d = Math.hypot(c[0] - x, c[1] - y);
        if (d < bestDist) { best = c; bestDist = d; }
    }
    return best && bestDist <= maxPx ? best : null;
};
const facingAt = (x, y) => (CHAIRS.find((c) => Math.hypot(c[0] - x, c[1] - y) <= 20) || [])[2];

// Resolves once the desk spawn is done, so the calendar check on entry starts right after it.
const deskSpawnDone = WA.onInit().then(async () => {
    const dbg = [];
    try {
        // An explicit position in the link (e.g. #start-area) wins.
        const hash = WA.room.hashParameters || {};
        const uuid = WA.player.uuid;
        dbg.push("uuid=" + uuid, "hashKeys=" + Object.keys(hash).join(","));
        // Only a real position in the link (non-empty hash value, e.g. #start-area) wins over the desk.
        if (Object.values(hash).some((v) => v !== undefined && v !== null && v !== "")) return;
        if (!uuid) return;
        const wamUrl = new URL("newoffice.wam", WA.room.mapURL).toString();
        dbg.push("wam=" + wamUrl);
        const res = await fetch(wamUrl, { cache: "no-store" });
        dbg.push("status=" + res.status);
        const wam = await res.json();
        const own = (wam.areas || []).find((area) =>
            (area.properties || []).some((p) => p.type === "personalAreaPropertyData" && p.ownerId === uuid)
        );
        dbg.push("own=" + (own ? own.name : "none"));
        if (!own) return;
        const spawn = SPAWNS[own.id] || [own.x + own.width / 2, own.y + own.height / 2];
        await WA.player.teleport(spawn[0], spawn[1]);
        if (spawn[2]) face(spawn[2]);
        dbg.push("teleported");
    } catch (e) {
        console.warn("elunic desk spawn failed", e);
        dbg.push("error=" + e);
    } finally {
        console.info("[elunic] desk spawn: " + dbg.join(" | "));
    }
});

// --- calendar meetings: during an accepted meeting, walk to the seat the wa-calendar service assigned, set
// "Do not disturb", and walk back + restore the previous status when the meeting ends. Meetings need a logged-in
// user (token); every player, anonymous ones included, pings so the service can list who is on the map.
WA.onInit().then(() => {
    let token;
    try { token = WA.player.userRoomToken; } catch (e) { token = undefined; }
    const api = new URL("/calendar-api/presence", WA.room.mapURL).toString();
    const status = (action) => window.parent.postMessage({ type: "elunic-status", action }, "*");
    const go = async (x, y) => {
        try {
            const r = await WA.player.moveTo(x, y, 10);
            if (r && r.cancelled) await WA.player.teleport(x, y);
        } catch (e) {
            await WA.player.teleport(x, y).catch(() => {});
        }
    };
    let active = null;   // { key, x, y, endsAt, back: {x, y} }
    const finished = new Set();   // "key|end" of meetings this page already left: a late answer never restarts them,
                                  // but an extended meeting (same key, later end) does
    let busy = false;
    let mine = null;      // own meeting from the last answer (also after "leave meeting", for a rejoin)
    let lastBack = null;  // desk position of the current meeting, kept for a rejoin
    async function leave() {
        finished.add(active.key + "|" + active.endsAt);
        const back = active.back;
        lastBack = back;
        active = null;
        scriptedMove = true;
        try {
            await go(back.x, back.y);
            // Sit down on the desk chair here, without a further walk: teleport does not reset the status, a walk
            // would turn the restored status back into online.
            const chair = nearestChair(back.x, back.y, 30);
            if (chair) {
                await WA.player.teleport(chair[0], chair[1]).catch(() => {});
                if (chair[2]) face(chair[2]);
            }
        } finally {
            scriptedMove = false;
        }
        status("restore");
    }
    let first = true;   // the first check right after entering the map
    // --- conversation guard (Andreas Ullrich-Lohr, 2026-11-10: a meeting start cut his call with a colleague):
    // a starting meeting never pulls the player out of a running conversation (proximity bubble). Instead a chip
    // offers "join meeting"; the player joins on click, or by itself after TALK_FREE_MS without any conversation.
    const TALK_FREE_MS = 15000;
    let inTalk = false;
    let talkEnded = 0;      // when the last conversation ended (0 = none on this page)
    let pending = null;     // meeting held back because of a conversation
    let joinTimer = null;
    const talkBlocks = () => inTalk || (talkEnded > 0 && Date.now() - talkEnded < TALK_FREE_MS);
    const scheduleAuto = () => {
        clearTimeout(joinTimer);
        joinTimer = null;
        if (!pending || inTalk) return;
        joinTimer = setTimeout(() => tick("auto"), Math.max(0, TALK_FREE_MS - (Date.now() - talkEnded)) + 300);
    };
    try {
        WA.player.proximityMeeting.onJoin().subscribe(() => { inTalk = true; scheduleAuto(); });
        WA.player.proximityMeeting.onLeave().subscribe(() => { inTalk = false; talkEnded = Date.now(); scheduleAuto(); });
    } catch (e) { console.warn("elunic calendar: no conversation events, meetings start without the guard", e); }
    // action: undefined (regular ping), "leave" (button), "rejoin" (walked back into the own meeting room),
    // "join" (button of a held-back meeting, also when walking into its room), "auto" (conversation over for 15 s)
    async function tick(action) {
        while (busy && action) await new Promise((r) => setTimeout(r, 200));
        if (busy) return;
        busy = true;
        try {
            // The meeting end is known locally: leave on time even if the service is slow or down.
            if (active && Date.now() >= active.endsAt) await leave();
            const who = WA.player.uuid + "|" + WA.player.name;
            // the position lets wa-calendar avoid rooms where somebody else stands when it picks a meeting room
            const pos = await WA.player.getPosition().catch(() => null);
            // ... and so do the positions of everybody this client sees: players whose own page still runs an older
            // script (no position in their ping) count too
            let others = [];
            try {
                others = Array.from(WA.players.list(), (p) => ({ uuid: p.uuid, name: p.name, x: p.position.x, y: p.position.y }));
            } catch (e) { /* tracking not ready yet */ }
            const body = { token: token || undefined, name: WA.player.name, id: WA.player.uuid, action,
                x: pos ? pos.x : undefined, y: pos ? pos.y : undefined, others };
            if (action === "rejoin" && mine) finished.delete(mine.key + "|" + mine.endsAt);
            const res = await fetch(api, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
                signal: AbortSignal.timeout(10000) }).catch(() => null);
            if (!res || !res.ok) return;   // service unreachable: never start or move a meeting
            const data = await res.json();
            let meeting = data.meeting;
            await updateLabels(Array.isArray(data.rooms) ? data.rooms : []);
            // The answer may be late: drop it if the meeting has ended meanwhile, was already left here, or the
            // player identity changed while it was on its way.
            if (who !== WA.player.uuid + "|" + WA.player.name) return;
            if (meeting && meeting.endsAt <= Date.now()) meeting = null;
            if (meeting && meeting.left) {
                // Left with the button (here or in another tab): back to the desk, keep the room for a rejoin.
                // Not subject to the left-meeting guard below, otherwise the rejoin context would get lost.
                mine = meeting;
                if (active && active.key === meeting.key) await leave();
                meeting = null;
            } else {
                if (meeting && finished.has(meeting.key + "|" + meeting.endsAt)) meeting = null;
                mine = meeting;
            }
            if (!meeting) pending = null;
            if (meeting && active && active.key === meeting.key) active.endsAt = meeting.endsAt;   // extended or shortened
            const starting = meeting && (!active || active.key !== meeting.key);
            if (starting && action !== "join" && talkBlocks()) {
                // in a conversation (or it ended less than 15 s ago): offer the meeting instead of walking away
                pending = meeting;
                scheduleAuto();
                return;
            }
            if (starting) { pending = null; clearTimeout(joinTimer); joinTimer = null; }
            if (meeting && (!active || active.key !== meeting.key || active.x !== meeting.x || active.y !== meeting.y)) {
                const back = active ? active.back : (action === "rejoin" && lastBack) || await WA.player.getPosition();
                active = { key: meeting.key, x: meeting.x, y: meeting.y, endsAt: meeting.endsAt, back };
                // "dnd" before the walk lets the bridge save the status from before the meeting; WorkAdventure resets
                // the status to online on every move, so "dnd" again after arriving (and after every later move).
                status("dnd");
                scriptedMove = true;
                try {
                    if (first) await WA.player.teleport(meeting.x, meeting.y).catch(() => go(meeting.x, meeting.y));   // entering mid-meeting: straight into the room
                    else await go(meeting.x, meeting.y);
                } finally {
                    scriptedMove = false;
                }
                const dir = facingAt(meeting.x, meeting.y);
                if (active && dir) face(dir);
                if (active) status("dnd");
            } else if (!meeting && active) {
                await leave();
            }
        } catch (e) {
            console.warn("elunic calendar", e);
        } finally {
            busy = false;
            first = false;
            refreshChip();
        }
    }

    // --- meeting rooms: a label with the meeting title in every room with a running meeting; inside the own meeting
    // room a chip (like the one of a personal desk area) and a button to leave the meeting and go back to the desk.
    const de = (navigator.language || "").toLowerCase().startsWith("de");
    const T = de
        ? { meeting: "Termin", private: "Privater Termin", room: "Terminraum", leave: "Termin verlassen und zum Platz zurück",
            pending: "Termin läuft", join: "Termin beitreten" }
        : { meeting: "Meeting", private: "Private meeting", room: "Meeting room", leave: "Leave meeting and go back to my desk",
            pending: "Meeting started", join: "Join meeting" };
    const labelText = (r) => r.title || (r.isPrivate ? T.private : T.meeting);
    const pageUrl = (page, text, button, variable) => new URL(page + "?t=" + encodeURIComponent(text) + (button ? "&b=" + encodeURIComponent(button) : "")
        + (variable ? "&v=" + encodeURIComponent(variable) : ""), WA.room.mapURL).toString();
    // Embedded websites get a white background from WorkAdventure: size the label frame to its text.
    const labelBox = (rect, text) => {
        const width = Math.min(rect[2] - 8, Math.round(34 + text.length * 7));
        return { x: rect[0] + Math.round((rect[2] - width) / 2), y: rect[1] - 27, width, height: 22 };   // on the wall above the room
    };
    const labels = new Map();   // roomId -> { text, site }
    async function updateLabels(rooms) {
        const seen = new Set();
        for (const r of rooms) {
            const rect = ROOM_RECTS[r.roomId];
            if (!rect || seen.has(r.roomId)) continue;
            seen.add(r.roomId);
            const text = labelText(r);
            const cur = labels.get(r.roomId);
            if (cur && cur.text === text) continue;
            if (cur) {
                labels.delete(r.roomId);
                await WA.room.website.delete("elunic-label-" + r.roomId).catch(() => {});
            }
            const site = WA.room.website.create({ name: "elunic-label-" + r.roomId, url: pageUrl("meeting-label.html", text),
                position: labelBox(rect, text), visible: true, allowApi: false, origin: "map", scale: 1 });
            labels.set(r.roomId, { text, site });
        }
        for (const id of [...labels.keys()]) {
            if (seen.has(id)) continue;
            labels.delete(id);
            WA.room.website.delete("elunic-label-" + id).catch(() => {});
        }
    }
    let currentRoom = null;
    let chip = null, chipText = "", chipBusy = Promise.resolve();
    function refreshChip() {
        chipBusy = chipBusy.then(async () => {
            // a held-back meeting wins: its chip carries "join meeting"
            const offer = !!pending;
            const show = offer || (currentRoom && active && mine && !mine.left && mine.roomId === currentRoom);
            const text = !show ? "" : offer ? T.pending + ": " + labelText(pending) : T.room + ": " + labelText(mine);
            if (text === chipText) return;
            chipText = text;
            if (chip) {
                const old = chip;
                chip = null;
                await old.close().catch(() => {});
            }
            if (!show) return;
            // The chip carries the "leave meeting" button (action bar buttons from scripts end up in a collapsed menu).
            chip = await WA.ui.website.open({ url: offer ? pageUrl("meeting-chip.html", text, T.join, "elunicMeetingJoin") : pageUrl("meeting-chip.html", text, T.leave),
                visible: true, allowApi: true,
                position: { vertical: "top", horizontal: "right" }, size: { width: "340px", height: "82px" }, margin: { top: "84px", right: "16px" } });
        }).catch((e) => console.warn("elunic meeting chip", e));
    }
    WA.player.state.onVariableChange("elunicMeetingLeave").subscribe(() => tick("leave"));
    WA.player.state.onVariableChange("elunicMeetingJoin").subscribe(() => tick("join"));
    for (const [id, rect] of Object.entries(ROOM_RECTS)) {
        const name = "elunic-room-" + id;
        WA.room.area.create({ name, x: rect[0], y: rect[1], width: rect[2], height: rect[3] });
        WA.room.area.onEnter(name).subscribe(() => {
            currentRoom = id;
            // Walking back into the own meeting after "leave meeting" joins it again (Do not disturb, seat).
            if (mine && mine.left && mine.roomId === id && !scriptedMove) tick("rejoin");
            // Walking into the room of a held-back meeting joins it.
            else if (pending && pending.roomId === id && !scriptedMove) tick("join");
            refreshChip();
        });
        WA.room.area.onLeave(name).subscribe(() => {
            if (currentRoom === id) currentRoom = null;
            refreshChip();
        });
    }
    // Moving resets the status to online. During a meeting, put "Do not disturb" back once the player stops.
    let settle;
    WA.player.onPlayerMove((ev) => {
        clearTimeout(settle);
        if (active && !ev.moving) settle = setTimeout(() => { if (active) status("dnd"); }, 500);
    });
    if (CALENDAR) deskSpawnDone.catch(() => {}).then(tick);   // right after the desk spawn has placed the player
    if (CALENDAR) setInterval(tick, 30000);
});

// --- chairs: stop close to a free chair and the player walks onto it (exactly centred) and turns to the table ---
WA.onInit().then(async () => {
    const SNAP_PX = 30;            // about one tile: walking past a chair does not pull the player onto it
    const TAKEN_PX = 16;           // another player this close to the chair centre sits on it
    try { await WA.players.configureTracking({ players: true, movement: true }); } catch (e) { console.warn(e); }
    const taken = (c) => {
        try {
            for (const p of WA.players.list()) {
                const pos = p.position;
                if (pos && Math.hypot(pos.x - c[0], pos.y - c[1]) <= TAKEN_PX) return true;
            }
        } catch (e) { /* no tracking: treat as free */ }
        return false;
    };
    WA.player.onPlayerMove((ev) => {
        if (ev.moving || scriptedMove) return;   // the calendar walk/teleport places the player itself
        let best = null, bestDist = Infinity;
        for (const c of CHAIRS) {
            const d = Math.hypot(c[0] - ev.x, c[1] - ev.y);
            if (d < bestDist) { best = c; bestDist = d; }
        }
        // The walk ends with a "stopped" event right on the chair (distance 0), which ends the loop.
        if (!best || bestDist < 1 || bestDist > SNAP_PX || taken(best)) return;
        if (seatBridge) sit(best);
        else WA.player.teleport(best[0], best[1]).catch(() => {});
    });
});

// --- gong: walk up to it, press space, enter a message; everybody in the room hears it and gets a message card that stays
// until they dismiss it. Everybody can react to it (quick reactions plus a full picker), see gong-card.html. ---
const GONG_EVENT = "elunic-gong";
// WA.room.mapURL is only available after WA.onInit(), so resolve URLs lazily.
const gongSound = () => new URL("elunic-gong.ogg", WA.room.mapURL).toString();
// Banner in the receiver's browser language: German for "de*", English otherwise. Only the fallback if the card cannot open.
function gongText(from, message) {
    return (navigator.language || "").toLowerCase().startsWith("de")
        ? from + " hat den Gong geschlagen: " + message
        : from + " hit the gong: " + message;
}
// Opens the message card, or hands the gong to the card that is already open (hash-only change, no reload).
// The card dedups by gong id, so it does not matter that it also receives the event itself.
let gongCardQueue = Promise.resolve();
function showGongCard(g) {
    gongCardQueue = gongCardQueue.then(async () => {
        const base = new URL("gong-card.html", WA.room.mapURL).toString();
        const payload = encodeURIComponent(JSON.stringify(g));
        const existing = (await WA.ui.website.getAll()).find((s) => s.url.indexOf("gong-card.html") >= 0);
        if (existing) { existing.url = base + "#add=" + payload; return; }
        await WA.ui.website.open({
            url: base + "#g=" + payload, allowApi: true, visible: true,
            position: { vertical: "top", horizontal: "right" },
            size: { width: "392px", height: "220px" }, margin: { top: "56px", right: "12px" },
        });
    }).catch((e) => {
        console.warn(e);
        WA.ui.banner.openBanner({
            id: "elunic-gong", text: gongText(g.from, g.message),
            bgColor: "#7a5a12", textColor: "#ffffff", closable: true, timeToClose: 30000,
        });
    });
}
function ringGong(g) {
    try { WA.sound.loadSound(gongSound()).play({ volume: 0.7, loop: false }); } catch (e) { console.warn(e); }
    showGongCard(g);
}
WA.onInit().then(() => {
    WA.room.area.create({ name: "elunic-gong", x: 704, y: 288, width: 192, height: 96 });
    let action;
    WA.room.area.onEnter("elunic-gong").subscribe(() => {
        action = WA.ui.displayActionMessage({
            // Browser language: German for "de*", English otherwise.
            message: (navigator.language || "").toLowerCase().startsWith("de") ? "Leertaste: Gong schlagen" : "Space: hit the gong",
            callback: () => WA.ui.modal.openModal({
                src: new URL("gong.html", WA.room.mapURL).toString(),
                title: "Gong", position: "center", allowApi: true, allow: "autoplay",
            }),
        });
    });
    WA.room.area.onLeave("elunic-gong").subscribe(() => { if (action) action.remove(); action = undefined; });
    // Senders ring locally in gong.html (which opens their own card); skip our own echo if the server reflects it.
    WA.event.on(GONG_EVENT).subscribe((ev) => {
        if (ev.senderId !== undefined && ev.senderId === WA.player.playerId) return;
        const d = ev.data || {};
        const from = String(d.from || "?"), message = String(d.message || "").slice(0, 200);
        // same fallback id as gong-card.html, for senders that predate the id
        ringGong({ id: String(d.id || (String(d.from) + "|" + String(d.message) + "|" + String(d.ts || ""))), from, message, ts: Number(d.ts) || Date.now() });
    });
});

// Companion bridge (2026-11-12, Andreas Ullrich-Lohr): the Starhunter Companion embeds this office as a small tile or an invisible tab.
// It tells the Companion when the player is in a conversation (proximity bubble) so the tile can grow by itself. Only when the play page
// is framed (window.top is then the Companion, not the play page); opened on its own nothing is sent. The message carries no names, only the state.
const toCompanion = (event, extra) => {
    try {
        if (window.top !== window.parent) window.top.postMessage(Object.assign({ type: "elunic-companion-wa", event }, extra), "*");
    } catch (e) { /* no framing page we can talk to */ }
};
WA.onInit().then(() => {
    toCompanion("hello");
    try {
        WA.player.proximityMeeting.onJoin().subscribe(() => toCompanion("meeting", { active: true }));
        WA.player.proximityMeeting.onLeave().subscribe(() => toCompanion("meeting", { active: false }));
    } catch (e) { console.warn("elunic companion bridge: no conversation events", e); }
});
